mapper.update:
update corgi_topics
set topic = #{topic.topic}, content = #{topic.content}, opuid = #{topic.opuid}, `status` = #{topic.status}
where id = #{topic.topicId}

mapper.delete:
delete from corgi_activity_message
where to_user_id = #{userId}
and `time` <= #{time}

mapper.update:
update corgi_activity_message
set is_read = '1'
where to_user_id = #{userId}
and `time` <= #{time}

    and `is_read` = #{isRead}

limit #{size}
